if (!list) throw new Error('Results list is missing');

const fragment = document.createDocumentFragment();
for (const label of ['HTML', 'CSS', 'JavaScript']) {
  const item = document.createElement('li');
  item.textContent = label;
  fragment.append(item);
}

list.replaceChildren(fragment);

const images = document.querySelectorAll('img[data-src]');
const observer = new IntersectionObserver((entries, currentObserver) => {
  for (const entry of entries) {
    if (!entry.isIntersecting) continue;
    const image = entry.target;
    if (!(image instanceof HTMLImageElement)) continue;
    const source = image.dataset.src;
    if (!source) continue;
    image.src = source;
    delete image.dataset.src;
    currentObserver.unobserve(image);
  }
}, { rootMargin: '200px' });

images.forEach((image) => observer.observe(image));
// In component teardown: observer.disconnect();

const panel = document.querySelector('#status-panel');
if (!panel) throw new Error('Status panel is missing');

const observer = new MutationObserver((records) => {
  for (const record of records) {
    console.log(record.type, record.target);
  }
});
observer.observe(panel, { childList: true, subtree: true, attributes: true });

// After the feature no longer needs observation:
observer.disconnect();

